; Shape-specialized example. Edit snackwell/kernels/inference.py and regenerate.
; Run: python3 scripts/run_kernel.py relu
; x: byte 0, 16 words
; out: byte 64, 16 words

; relu: 4 rows x 4 columns
; Generated by snackwell/kernels/inference.py. Launch warp 0, mask 0xf.
; All addresses are bytes; R15 is explicitly initialized to zero.
XOR R15, R15, R15
TID R12
ADD R12, R12, R12
ADD R12, R12, R12
ADD R12, R12, R12
ADD R12, R12, R12
ADDI R12, R12, 0
TID R13
ADD R13, R13, R13
ADD R13, R13, R13
ADD R13, R13, R13
ADD R13, R13, R13
ADDI R13, R13, 64
ADDI R14, R15, 1
row_group:
LD_SHARED R0, [R12 + 0]
FLT R1, R0, R15
SUB R1, R15, R1
XOR R2, R0, R15
AND R2, R2, R1
XOR R0, R0, R2
ST_SHARED [R13 + 0], R0
LD_SHARED R0, [R12 + 4]
FLT R1, R0, R15
SUB R1, R15, R1
XOR R2, R0, R15
AND R2, R2, R1
XOR R0, R0, R2
ST_SHARED [R13 + 4], R0
LD_SHARED R0, [R12 + 8]
FLT R1, R0, R15
SUB R1, R15, R1
XOR R2, R0, R15
AND R2, R2, R1
XOR R0, R0, R2
ST_SHARED [R13 + 8], R0
LD_SHARED R0, [R12 + 12]
FLT R1, R0, R15
SUB R1, R15, R1
XOR R2, R0, R15
AND R2, R2, R1
XOR R0, R0, R2
ST_SHARED [R13 + 12], R0
ADDI R12, R12, 64
ADDI R13, R13, 64
ADDI R14, R14, -1
BEQ R14, R15, done
BEQ R15, R15, row_group
done: EXIT
